def get_user_message_count(user):
    count = 0
    for channel in get_channels():
        messages = read_channel_messages(channel)
        for message in messages:
            if message.sender == user:
                count += 1
    return count

def sort_users_by_message_count():
    users = set()
    for channel in get_channels():
        messages = read_channel_messages(channel)
        for message in messages:
            users.add(message.sender)

    user_message_counts = {user: get_user_message_count(user) for user in users}
    sorted_users = sorted(user_message_counts, key=lambda x: (-user_message_counts[x], x))

    for i, user in enumerate(sorted_users):
        send_direct_message(user, f"Congrats on being the {i+1}-th most active user!")

sort_users_by_message_count()
